// ABOUTME: Property tests for the trial balance, generated by a seeded fast-check run so a failure
// ABOUTME: reproduces: for randomly generated balanced entries the debits equal the credits, the
// ABOUTME: trial balance nets to zero, and reversing an entry returns every account to where it was.

import { allocate, fromMinor, isZero, type CurrencyCode } from '@/domain/money';
import * as fc from 'fast-check';
import { describe, expect, it } from 'vitest';

import {
  createJournalEntry,
  deriveTrialBalance,
  netOfTrialBalance,
  reverseJournalEntry,
  type JournalEntry,
  type JournalEntryInput,
  type JournalLineInput,
} from '..';

const OPTIONS = { seed: 20261022, numRuns: 200 } as const;
const CURRENCIES = ['KES', 'UGX', 'USD', 'KWD', 'JPY'] as const;

/**
 * A balanced entry: the debit amounts are drawn at random, and the credits are the largest-remainder
 * split of their total, so the two sides sum to the same amount by construction.
 */
const balancedEntry = fc
  .constantFrom<CurrencyCode>(...CURRENCIES)
  .chain((currency) =>
    fc
      .array(fc.integer({ min: 1, max: 10_000_000 }), { minLength: 1, maxLength: 4 })
      .chain((debits) =>
        fc
          .array(fc.integer({ min: 1, max: 1_000 }), {
            minLength: debits.length,
            maxLength: debits.length,
          })
          .map((weights) => {
            const total = debits.reduce((running, amount) => running + amount, 0);
            const credits = allocate(fromMinor(total, currency), weights).map(
              (part) => part.amount_minor
            );
            return { currency, debits, credits };
          })
      )
  )
  .filter((generated) => generated.credits.every((amount) => amount > 0));

function entryOf(generated: {
  currency: CurrencyCode;
  debits: readonly number[];
  credits: readonly number[];
}): JournalEntry {
  const lines: JournalLineInput[] = [
    ...generated.debits.map((amount, index) => ({
      accountCode: `1${100 + index}`,
      debit: fromMinor(amount, generated.currency),
    })),
    ...generated.credits.map((amount, index) => ({
      accountCode: `4${100 + index}`,
      credit: fromMinor(amount, generated.currency),
    })),
  ];
  const input: JournalEntryInput = {
    institutionId: 'inst-1',
    entryDate: '2027-02-10',
    source: { kind: 'invoice', id: `invoice-${generated.debits.join('-')}` },
    narration: 'generated',
    lines,
  };
  return createJournalEntry(input);
}

describe('a generated balanced entry', () => {
  it('is accepted, and its debits equal its credits', () => {
    fc.assert(
      fc.property(balancedEntry, (generated) => {
        const entry = entryOf(generated);
        expect(entry.totalDebit.amount_minor).toBe(entry.totalCredit.amount_minor);
        expect(entry.totalDebit.amount_minor).toBe(
          generated.debits.reduce((running, amount) => running + amount, 0)
        );
        expect(entry.lines).toHaveLength(generated.debits.length + generated.credits.length);
      }),
      OPTIONS
    );
  });

  it('nets to zero in the trial balance, and the trial balance balances', () => {
    fc.assert(
      fc.property(balancedEntry, (generated) => {
        const entry = entryOf(generated);
        const balance = deriveTrialBalance([entry], generated.currency);
        expect(balance.balanced).toBe(true);
        expect(balance.totalDebit).toEqual(balance.totalCredit);
        expect(isZero(netOfTrialBalance(balance))).toBe(true);
      }),
      OPTIONS
    );
  });

  it('leaves every account where it was once it is reversed', () => {
    fc.assert(
      fc.property(balancedEntry, (generated) => {
        const entry = entryOf(generated);
        const reversal = reverseJournalEntry(entry, { reason: 'generated reversal' });
        const balance = deriveTrialBalance([entry, reversal], generated.currency);
        expect(balance.balanced).toBe(true);
        for (const row of balance.rows) expect(isZero(row.balance)).toBe(true);
        expect(isZero(netOfTrialBalance(balance))).toBe(true);
      }),
      OPTIONS
    );
  });
});

describe('a batch of generated entries', () => {
  it('always balances, whatever mix of currencies and amounts it holds', () => {
    fc.assert(
      fc.property(fc.array(balancedEntry, { minLength: 1, maxLength: 8 }), (generated) => {
        const entries = generated.map(entryOf);
        for (const currency of CURRENCIES) {
          const balance = deriveTrialBalance(entries, currency);
          expect(balance.balanced).toBe(true);
          expect(isZero(netOfTrialBalance(balance))).toBe(true);
        }
      }),
      OPTIONS
    );
  });

  it('counts only the entries of the currency it is derived in', () => {
    fc.assert(
      fc.property(balancedEntry, balancedEntry, (first, second) => {
        const entries = [entryOf(first), entryOf(second)];
        for (const currency of CURRENCIES) {
          const expected = entries.filter((entry) => entry.currency === currency);
          const balance = deriveTrialBalance(entries, currency);
          expect(balance.rows.length === 0).toBe(expected.length === 0);
        }
      }),
      OPTIONS
    );
  });
});

describe('the full amount range', () => {
  it('balances two postings near the largest amount the money module holds', () => {
    const entry = createJournalEntry({
      institutionId: 'inst-1',
      entryDate: '2027-02-10',
      source: { kind: 'invoice', id: 'invoice-big' },
      narration: 'big',
      lines: [
        { accountCode: '1100', debit: fromMinor(4_500_000_000_000_000, 'KES') },
        { accountCode: '4000', credit: fromMinor(4_500_000_000_000_000, 'KES') },
      ],
    });
    const balance = deriveTrialBalance([entry, entry], 'KES');
    expect(balance.balanced).toBe(true);
    expect(balance.totalDebit.amount_minor).toBe(9_000_000_000_000_000);
    expect(isZero(netOfTrialBalance(balance))).toBe(true);
  });

  it('balances a thousand one-cent postings exactly', () => {
    const entries = Array.from({ length: 1_000 }, (_, index) =>
      createJournalEntry({
        institutionId: 'inst-1',
        entryDate: '2027-02-10',
        source: { kind: 'invoice', id: `invoice-${index}` },
        narration: 'cent',
        lines: [
          { accountCode: '1100', debit: fromMinor(1, 'KES') },
          { accountCode: '4000', credit: fromMinor(1, 'KES') },
        ],
      })
    );
    const balance = deriveTrialBalance(entries, 'KES');
    expect(balance.totalDebit.amount_minor).toBe(1_000);
    expect(balance.balanced).toBe(true);
  });
});
